package com.example.budgetlife

import org.json.JSONArray
import org.json.JSONObject
import java.util.UUID
import kotlin.math.roundToLong

fun uid(prefix: String): String = prefix + "_" + UUID.randomUUID().toString().replace("-", "").take(12)
fun JSONObject.str(key: String, def: String = ""): String = if (has(key) && !isNull(key)) optString(key, def) else def
fun JSONObject.dbl(key: String, def: Double = 0.0): Double = if (has(key) && !isNull(key)) optDouble(key, def) else def
fun JSONObject.int(key: String, def: Int = 0): Int = if (has(key) && !isNull(key)) optInt(key, def) else def
fun JSONObject.bool(key: String, def: Boolean = false): Boolean = if (has(key) && !isNull(key)) optBoolean(key, def) else def
fun JSONObject.obj(key: String): JSONObject = if (has(key) && !isNull(key)) optJSONObject(key) ?: JSONObject() else JSONObject()
fun JSONObject.arr(key: String): JSONArray = if (has(key) && !isNull(key)) optJSONArray(key) ?: JSONArray() else JSONArray()
fun JSONArray.objects(): List<JSONObject> = (0 until length()).mapNotNull { optJSONObject(it) }
fun JSONArray.strings(): List<String> = (0 until length()).map { optString(it) }
fun List<JSONObject>.toJsonArray(): JSONArray = JSONArray().also { a -> forEach { a.put(it) } }
fun round2(v: Double): Double = (v * 100.0).roundToLong() / 100.0

data class Category(val id: String, var name: String, var kind: String, var color: String, var icon: String, var budgetMonthly: Double? = null, var order: Int = 0) {
    fun toJson() = JSONObject().apply { put("id", id); put("name", name); put("kind", kind); put("color", color); put("icon", icon); budgetMonthly?.let { put("budgetMonthly", it) }; put("order", order) }
    companion object { fun from(o: JSONObject) = Category(o.str("id", uid("cat")), o.str("name", "Категория"), o.str("kind", "expense"), o.str("color", "#38c3f5"), o.str("icon", "Circle"), if (o.has("budgetMonthly") && !o.isNull("budgetMonthly")) o.dbl("budgetMonthly") else null, o.int("order")) }
}

data class InterestConfig(var enabled: Boolean = false, var annualRate: Double = 0.0, var capitalization: String = "monthly", var payoutDay: Int? = null, var payoutMode: String = "compound", var payoutAccountId: String? = null, var monthlyTopUp: Double = 0.0, var topUpDay: Int = 5, var topUpStartYM: String? = null, var topUpEndYM: String? = null, var termStart: String? = null, var termEnd: String? = null) {
    fun toJson() = JSONObject().apply { put("enabled", enabled); put("annualRate", annualRate); put("capitalization", capitalization); payoutDay?.let { put("payoutDay", it) }; put("payoutMode", payoutMode); payoutAccountId?.let { put("payoutAccountId", it) }; put("monthlyTopUp", monthlyTopUp); put("topUpDay", topUpDay); topUpStartYM?.let { put("topUpStartYM", it) }; topUpEndYM?.let { put("topUpEndYM", it) }; termStart?.let { put("termStart", it) }; termEnd?.let { put("termEnd", it) } }
    companion object { fun from(o: JSONObject) = InterestConfig(o.bool("enabled"), o.dbl("annualRate"), o.str("capitalization", "monthly"), if (o.has("payoutDay") && !o.isNull("payoutDay")) o.int("payoutDay") else null, o.str("payoutMode", "compound"), o.optString("payoutAccountId").takeIf { it.isNotBlank() }, o.dbl("monthlyTopUp"), o.int("topUpDay", 5), o.optString("topUpStartYM").takeIf { it.isNotBlank() }, o.optString("topUpEndYM").takeIf { it.isNotBlank() }, o.optString("termStart").takeIf { it.isNotBlank() }, o.optString("termEnd").takeIf { it.isNotBlank() }) }
}

data class Account(val id: String, var name: String, var type: String = "card", var currency: String = "RUB", var balance: Double = 0.0, var color: String = "#38c3f5", var icon: String = "CreditCard", var note: String? = null, var includeInTotal: Boolean = true, var archived: Boolean = false, var order: Long = System.currentTimeMillis(), var interest: InterestConfig = InterestConfig(), var creditLimit: Double? = null) {
    fun toJson() = JSONObject().apply { put("id", id); put("name", name); put("type", type); put("currency", currency); put("balance", balance); put("color", color); put("icon", icon); note?.let { put("note", it) }; put("includeInTotal", includeInTotal); put("archived", archived); put("order", order); put("interest", interest.toJson()); creditLimit?.let { put("creditLimit", it) } }
    companion object { fun from(o: JSONObject) = Account(o.str("id", uid("acc")), o.str("name", "Счёт"), o.str("type", "card"), o.str("currency", "RUB"), o.dbl("balance"), o.str("color", "#38c3f5"), o.str("icon", "CreditCard"), o.optString("note").takeIf { it.isNotBlank() }, o.bool("includeInTotal", true), o.bool("archived"), if (o.has("order")) o.optLong("order") else System.currentTimeMillis(), InterestConfig.from(o.obj("interest")), if (o.has("creditLimit") && !o.isNull("creditLimit")) o.dbl("creditLimit") else null) }
}

data class PayDay(val id: String, var label: String, var day: Int, var share: Double? = null, var amount: Double? = null, var rule: String = "prevWorkday") {
    fun toJson() = JSONObject().apply { put("id", id); put("label", label); put("day", day); share?.let { put("share", it) }; amount?.let { put("amount", it) }; put("rule", rule) }
    companion object { fun from(o: JSONObject) = PayDay(o.str("id", uid("pd")), o.str("label", "Выплата"), o.int("day", 10), if (o.has("share") && !o.isNull("share")) o.dbl("share") else null, if (o.has("amount") && !o.isNull("amount")) o.dbl("amount") else null, o.str("rule", "prevWorkday")) }
}

data class PayDayOverride(val id: String, var date: String? = null, var amount: Double? = null, var skipped: Boolean = false) {
    fun toJson() = JSONObject().apply { put("id", id); date?.let { put("date", it) }; amount?.let { put("amount", it) }; put("skipped", skipped) }
    companion object { fun from(o: JSONObject) = PayDayOverride(o.str("id"), o.optString("date").takeIf { it.isNotBlank() }, if (o.has("amount") && !o.isNull("amount")) o.dbl("amount") else null, o.bool("skipped")) }
}

data class MonthOverride(var amount: Double? = null, var payDays: MutableList<PayDayOverride> = mutableListOf(), var skip: Boolean = false, var note: String? = null) {
    fun toJson() = JSONObject().apply { amount?.let { put("amount", it) }; put("payDays", payDays.map { it.toJson() }.toJsonArray()); put("skip", skip); note?.let { put("note", it) } }
    companion object { fun from(o: JSONObject) = MonthOverride(if (o.has("amount") && !o.isNull("amount")) o.dbl("amount") else null, o.arr("payDays").objects().map { PayDayOverride.from(it) }.toMutableList(), o.bool("skip"), o.optString("note").takeIf { it.isNotBlank() }) }
}

data class IncomeSource(val id: String, var name: String, var kind: String = "salary", var accountId: String, var currency: String = "RUB", var amount: Double = 0.0, var variable: Boolean = false, var payDays: MutableList<PayDay> = mutableListOf(), var startYM: String, var endYM: String? = null, var categoryId: String? = null, var note: String? = null, var active: Boolean = true, var taxEnabled: Boolean = false, var taxRate: Double = 0.0, var overrides: MutableMap<String, MonthOverride> = mutableMapOf(), var order: Int = 0) {
    fun toJson() = JSONObject().apply { put("id", id); put("name", name); put("kind", kind); put("accountId", accountId); put("currency", currency); put("amount", amount); put("variable", variable); put("payDays", payDays.map { it.toJson() }.toJsonArray()); put("startYM", startYM); endYM?.let { put("endYM", it) }; categoryId?.let { put("categoryId", it) }; note?.let { put("note", it) }; put("active", active); put("tax", JSONObject().apply { put("enabled", taxEnabled); put("rate", taxRate) }); put("overrides", JSONObject().also { ov -> overrides.forEach { (k, v) -> ov.put(k, v.toJson()) } }); put("order", order) }
    companion object { fun from(o: JSONObject): IncomeSource { val tax = o.obj("tax"); val ov = mutableMapOf<String, MonthOverride>(); val ovObj = o.obj("overrides"); ovObj.keys().forEach { k -> ov[k] = MonthOverride.from(ovObj.obj(k)) }; return IncomeSource(o.str("id", uid("inc")), o.str("name", "Доход"), o.str("kind", "salary"), o.str("accountId"), o.str("currency", "RUB"), o.dbl("amount"), o.bool("variable"), o.arr("payDays").objects().map { PayDay.from(it) }.toMutableList(), o.str("startYM", Dates.nowYM()), o.optString("endYM").takeIf { it.isNotBlank() }, o.optString("categoryId").takeIf { it.isNotBlank() }, o.optString("note").takeIf { it.isNotBlank() }, o.bool("active", true), tax.bool("enabled"), tax.dbl("rate"), ov, o.int("order")) } }
}

data class Subscription(val id: String, var name: String, var amount: Double, var currency: String = "RUB", var every: Int = 1, var unit: String = "month", var startDate: String, var endDate: String? = null, var categoryId: String? = null, var accountId: String, var active: Boolean = true, var autoRenew: Boolean = true, var remindDays: Int = 1, var note: String? = null, var trialUntil: String? = null, var priceHistory: MutableList<Pair<String, Double>> = mutableListOf(), var color: String = "#8b5cf6", var icon: String = "Repeat") {
    fun toJson() = JSONObject().apply { put("id", id); put("name", name); put("amount", amount); put("currency", currency); put("cycle", JSONObject().apply { put("every", every); put("unit", unit) }); put("startDate", startDate); endDate?.let { put("endDate", it) }; categoryId?.let { put("categoryId", it) }; put("accountId", accountId); put("active", active); put("autoRenew", autoRenew); put("remindDays", remindDays); note?.let { put("note", it) }; trialUntil?.let { put("trialUntil", it) }; put("priceHistory", priceHistory.map { JSONObject().apply { put("from", it.first); put("amount", it.second) } }.toJsonArray()); put("color", color); put("icon", icon) }
    companion object { fun from(o: JSONObject): Subscription { val c = o.obj("cycle"); return Subscription(o.str("id", uid("sub")), o.str("name", "Подписка"), o.dbl("amount"), o.str("currency", "RUB"), c.int("every", 1).coerceAtLeast(1), c.str("unit", "month"), o.str("startDate", Dates.today()), o.optString("endDate").takeIf { it.isNotBlank() }, o.optString("categoryId").takeIf { it.isNotBlank() }, o.str("accountId"), o.bool("active", true), o.bool("autoRenew", true), o.int("remindDays", 1), o.optString("note").takeIf { it.isNotBlank() }, o.optString("trialUntil").takeIf { it.isNotBlank() }, o.arr("priceHistory").objects().map { it.str("from") to it.dbl("amount") }.toMutableList(), o.str("color", "#8b5cf6"), o.str("icon", "Repeat")) } }
}

data class Credit(val id: String, var name: String, var kind: String = "loan", var accountId: String, var currency: String = "RUB", var principal: Double = 0.0, var annualRate: Double = 0.0, var termMonths: Int = 12, var startDate: String, var paymentDay: Int = 15, var paymentType: String = "annuity", var currentBalance: Double? = null, var limit: Double? = null, var used: Double? = null, var graceDays: Int? = null, var statementDay: Int? = null, var gracePaymentDay: Int? = null, var minPaymentPercent: Double? = null, var minPaymentFixed: Double? = null, var repayMode: String = "min", var customRepayAmount: Double? = null, var extraPayment: Double = 0.0, var note: String? = null, var color: String = "#f43f5e", var active: Boolean = true) {
    fun toJson() = JSONObject().apply { put("id", id); put("name", name); put("kind", kind); put("accountId", accountId); put("currency", currency); put("principal", principal); put("annualRate", annualRate); put("termMonths", termMonths); put("startDate", startDate); put("paymentDay", paymentDay); put("paymentType", paymentType); currentBalance?.let { put("currentBalance", it) }; limit?.let { put("limit", it) }; used?.let { put("used", it) }; graceDays?.let { put("graceDays", it) }; statementDay?.let { put("statementDay", it) }; gracePaymentDay?.let { put("gracePaymentDay", it) }; minPaymentPercent?.let { put("minPaymentPercent", it) }; minPaymentFixed?.let { put("minPaymentFixed", it) }; put("repayMode", repayMode); customRepayAmount?.let { put("customRepayAmount", it) }; put("extraPayment", extraPayment); note?.let { put("note", it) }; put("color", color); put("active", active) }
    companion object { fun from(o: JSONObject) = Credit(o.str("id", uid("cr")), o.str("name", "Кредит"), o.str("kind", "loan"), o.str("accountId"), o.str("currency", "RUB"), o.dbl("principal"), o.dbl("annualRate"), o.int("termMonths", 12), o.str("startDate", Dates.today()), o.int("paymentDay", 15), o.str("paymentType", "annuity"), if (o.has("currentBalance") && !o.isNull("currentBalance")) o.dbl("currentBalance") else null, if (o.has("limit") && !o.isNull("limit")) o.dbl("limit") else null, if (o.has("used") && !o.isNull("used")) o.dbl("used") else null, if (o.has("graceDays") && !o.isNull("graceDays")) o.int("graceDays") else null, if (o.has("statementDay") && !o.isNull("statementDay")) o.int("statementDay") else null, if (o.has("gracePaymentDay") && !o.isNull("gracePaymentDay")) o.int("gracePaymentDay") else null, if (o.has("minPaymentPercent") && !o.isNull("minPaymentPercent")) o.dbl("minPaymentPercent") else null, if (o.has("minPaymentFixed") && !o.isNull("minPaymentFixed")) o.dbl("minPaymentFixed") else null, o.str("repayMode", "min"), if (o.has("customRepayAmount") && !o.isNull("customRepayAmount")) o.dbl("customRepayAmount") else null, o.dbl("extraPayment"), o.optString("note").takeIf { it.isNotBlank() }, o.str("color", "#f43f5e"), o.bool("active", true)) }
}

data class Transaction(val id: String, var date: String, var amount: Double, var currency: String, var accountId: String, var toAccountId: String? = null, var categoryId: String? = null, var title: String, var note: String? = null, var kind: String, var status: String = "planned", var sourceType: String = "manual", var sourceId: String? = null, var sourceKey: String? = null, var recurrenceEvery: Int? = null, var recurrenceUnit: String? = null, var recurrenceUntil: String? = null, var plannedAmount: Double? = null, var tags: MutableList<String> = mutableListOf(), var createdAt: Long = System.currentTimeMillis(), var updatedAt: Long = System.currentTimeMillis()) {
    fun toJson() = JSONObject().apply { put("id", id); put("date", date); put("amount", amount); put("currency", currency); put("accountId", accountId); toAccountId?.let { put("toAccountId", it) }; categoryId?.let { put("categoryId", it) }; put("title", title); note?.let { put("note", it) }; put("kind", kind); put("status", status); put("sourceType", sourceType); sourceId?.let { put("sourceId", it) }; sourceKey?.let { put("sourceKey", it) }; if (recurrenceEvery != null) put("recurrence", JSONObject().apply { put("every", recurrenceEvery); put("unit", recurrenceUnit ?: "month"); recurrenceUntil?.let { put("until", it) } }); plannedAmount?.let { put("plannedAmount", it) }; put("tags", JSONArray(tags)); put("createdAt", createdAt); put("updatedAt", updatedAt) }
    companion object { fun from(o: JSONObject): Transaction { val r = o.obj("recurrence"); return Transaction(o.str("id", uid("tx")), o.str("date", Dates.today()), o.dbl("amount"), o.str("currency", "RUB"), o.str("accountId"), o.optString("toAccountId").takeIf { it.isNotBlank() }, o.optString("categoryId").takeIf { it.isNotBlank() }, o.str("title", "Операция"), o.optString("note").takeIf { it.isNotBlank() }, o.str("kind", if (o.dbl("amount") < 0) "expense" else "income"), o.str("status", "planned"), o.str("sourceType", "manual"), o.optString("sourceId").takeIf { it.isNotBlank() }, o.optString("sourceKey").takeIf { it.isNotBlank() }, if (r.has("every")) r.int("every") else null, if (r.has("unit")) r.str("unit") else null, r.optString("until").takeIf { it.isNotBlank() }, if (o.has("plannedAmount") && !o.isNull("plannedAmount")) o.dbl("plannedAmount") else null, o.arr("tags").strings().toMutableList(), if (o.has("createdAt")) o.optLong("createdAt") else System.currentTimeMillis(), if (o.has("updatedAt")) o.optLong("updatedAt") else System.currentTimeMillis()) } }
}

data class Settings(var baseCurrency: String = "RUB", var ratesProvider: String = "auto", var manualRates: MutableMap<String, Double> = mutableMapOf(), var theme: String = "dark", var hideBalances: Boolean = false, var showCents: Boolean = true, var monthStartDay: Int = 1, var firstDayOfWeek: Int = 1, var workweekOnly: Boolean = false, var locale: String = "ru-RU", var demoLoaded: Boolean = false, var onboarded: Boolean = false) {
    fun toJson() = JSONObject().apply { put("baseCurrency", baseCurrency); put("ratesProvider", ratesProvider); put("manualRates", JSONObject().also { m -> manualRates.forEach { (k, v) -> m.put(k, v) } }); put("theme", theme); put("hideBalances", hideBalances); put("showCents", showCents); put("monthStartDay", monthStartDay); put("firstDayOfWeek", firstDayOfWeek); put("workweekOnly", workweekOnly); put("locale", locale); put("demoLoaded", demoLoaded); put("onboarded", onboarded) }
    companion object { fun from(o: JSONObject): Settings { val m = mutableMapOf<String, Double>(); val mo = o.obj("manualRates"); mo.keys().forEach { m[it] = mo.dbl(it) }; return Settings(o.str("baseCurrency", "RUB"), o.str("ratesProvider", "auto"), m, o.str("theme", "dark"), o.bool("hideBalances"), o.bool("showCents", true), o.int("monthStartDay", 1), o.int("firstDayOfWeek", 1), o.bool("workweekOnly"), o.str("locale", "ru-RU"), o.bool("demoLoaded"), o.bool("onboarded")) } }
}

data class RatesSnapshot(var provider: String, var base: String, var date: String, var fetchedAt: Long, var rates: MutableMap<String, Double>) {
    fun toJson() = JSONObject().apply { put("provider", provider); put("base", base); put("date", date); put("fetchedAt", fetchedAt); put("rates", JSONObject().also { r -> rates.forEach { (k, v) -> r.put(k, v) } }) }
    companion object { fun from(o: JSONObject): RatesSnapshot { val m = mutableMapOf<String, Double>(); val ro = o.obj("rates"); ro.keys().forEach { m[it] = ro.dbl(it) }; return RatesSnapshot(o.str("provider"), o.str("base", "RUB"), o.str("date", Dates.today()), if (o.has("fetchedAt")) o.optLong("fetchedAt") else 0L, m) } }
}

class AppState {
    var version: Int = 1
    var accounts: MutableList<Account> = mutableListOf()
    var categories: MutableList<Category> = mutableListOf()
    var incomes: MutableList<IncomeSource> = mutableListOf()
    var subscriptions: MutableList<Subscription> = mutableListOf()
    var credits: MutableList<Credit> = mutableListOf()
    var transactions: MutableList<Transaction> = mutableListOf()
    var rates: RatesSnapshot? = null
    var settings: Settings = Settings()
    var updatedAt: Long = System.currentTimeMillis()

    fun toJson() = JSONObject().apply { put("version", version); put("accounts", accounts.map { it.toJson() }.toJsonArray()); put("categories", categories.map { it.toJson() }.toJsonArray()); put("incomes", incomes.map { it.toJson() }.toJsonArray()); put("subscriptions", subscriptions.map { it.toJson() }.toJsonArray()); put("credits", credits.map { it.toJson() }.toJsonArray()); put("transactions", transactions.map { it.toJson() }.toJsonArray()); rates?.let { put("rates", it.toJson()) } ?: put("rates", JSONObject.NULL); put("settings", settings.toJson()); put("updatedAt", updatedAt) }

    companion object {
        fun defaults(): AppState { val s = AppState(); s.categories = defaultCategories().toMutableList(); return s }
        fun fromJson(root: JSONObject): AppState { val s = defaults(); s.version = root.int("version", 1); s.accounts = root.arr("accounts").objects().map { Account.from(it) }.toMutableList(); if (root.has("categories")) s.categories = root.arr("categories").objects().map { Category.from(it) }.toMutableList(); s.incomes = root.arr("incomes").objects().map { IncomeSource.from(it) }.toMutableList(); s.subscriptions = root.arr("subscriptions").objects().map { Subscription.from(it) }.toMutableList(); s.credits = root.arr("credits").objects().map { Credit.from(it) }.toMutableList(); s.transactions = root.arr("transactions").objects().map { Transaction.from(it) }.toMutableList(); if (root.has("rates") && !root.isNull("rates")) s.rates = RatesSnapshot.from(root.obj("rates")); s.settings = Settings.from(root.obj("settings")); s.updatedAt = if (root.has("updatedAt")) root.optLong("updatedAt") else System.currentTimeMillis(); return s }

        fun defaultCategories(): List<Category> {
            val exp = listOf("Жильё" to "#38c3f5", "Еда и продукты" to "#10d19a", "Транспорт" to "#60a5fa", "Здоровье" to "#f43f5e", "Развлечения" to "#8b5cf6", "Одежда" to "#fb7d8e", "Связь и интернет" to "#34e5b0", "Образование" to "#a78bfa", "Подарки" to "#f472b6", "Путешествия" to "#38bdf8", "Спорт" to "#4ade80", "Кафе и рестораны" to "#fbbf5c", "Подписки" to "#c084fc", "Красота" to "#f472b6", "Прочее" to "#94a3b8")
            val inc = listOf("Зарплата" to "#10d19a", "Аванс" to "#34e5b0", "Фриланс" to "#38c3f5", "Проценты" to "#a78bfa", "Аренда" to "#60a5fa", "Дивиденды" to "#4ade80", "Подарки" to "#f472b6", "Кэшбэк" to "#fbbf5c", "Прочее" to "#94a3b8")
            return exp.mapIndexed { i, (n, c) -> Category(uid("cat"), n, "expense", c, "Circle", null, i) } + inc.mapIndexed { i, (n, c) -> Category(uid("cat"), n, "income", c, "Circle", null, i) }
        }
    }
}
